 "content": "from collections import Counter


def transform(grid):
    """Move the grid contents down by one row, filling the top with background."""
    if not grid:
        return []
    height = len(grid)
    width = len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    return [[background] * width] + [row[:] for row in grid[:height - 1]]
